const input = $json.body ?? $json;
const text = String(input.message ?? input.seller_message ?? input.body ?? '').trim();
const normalized = text.toLowerCase();
const dealId = input.deal_id ?? null;
const leadId = input.lead_id ?? null;
const propertyId = input.property_id ?? null;
const identityOk = Boolean(dealId && leadId && propertyId);
const blockers = Array.isArray(input.blockers) ? input.blockers : [];

const moneyMatches = text.match(/(?:\$\s*)?\b\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?\b/g) || [];
const amounts = moneyMatches.map(v => Number(v.replace(/[$,\s]/g,''))).filter(Number.isFinite);
const counteroffer = amounts.length ? amounts[0] : null;

let classification = 'other_response';
if (!text) classification = 'no_response';
else if (/\b(no|not interested|pass|decline|declined|never mind|sold already)\b/.test(normalized)) classification = 'rejected';
else if (/\b(yes|yeah|yep|okay|ok|deal|accept|accepted|let's do it|lets do it)\b/.test(normalized) && !/\bhow|what|when|where|why\b/.test(normalized)) classification = 'accepted';
else if (counteroffer !== null && /\b(offer|take|would take|can do|need|want|price|cash)\b/.test(normalized)) classification = 'counteroffer';
else if (/\b(how much|what can you offer|what's your offer|whats your offer|when can you close|how does this work|what are the terms|why)\b/.test(normalized)) classification = 'question';
else if (/\b(call me|text me|send|email|talk|interested|maybe|possibly|think about it)\b/.test(normalized)) classification = 'other_response';

const dynamicMao = Number(input.dynamic_mao ?? input.adjusted_mao ?? input.mao);
const aboveMao = Number.isFinite(counteroffer) && Number.isFinite(dynamicMao) && counteroffer > dynamicMao;
const withinMao = Number.isFinite(counteroffer) && Number.isFinite(dynamicMao) && counteroffer <= dynamicMao;

let route = 'WF-126';
let status = 'needs_review';
let humanReview = true;

if (!identityOk || blockers.length) {
  route = 'WF-126';
  status = 'blocked';
} else if (classification === 'accepted') {
  route = 'WF-266';
  status = 'accepted_pending_negotiation_decision';
} else if (classification === 'counteroffer') {
  route = withinMao ? 'WF-266' : aboveMao ? 'WF-267' : 'WF-266';
  status = withinMao ? 'counteroffer_within_mao' : aboveMao ? 'counteroffer_above_mao' : 'counteroffer_amount_uncertain';
  humanReview = !withinMao;
} else if (classification === 'rejected') {
  route = 'WF-261';
  status = 'rejected_reengagement';
  humanReview = false;
} else if (classification === 'question') {
  route = 'WF-266';
  status = 'seller_question';
} else if (classification === 'no_response') {
  route = 'WF-261';
  status = 'no_response_reengagement';
  humanReview = false;
} else {
  route = 'WF-266';
  status = 'other_response_review';
}

return [{ json: {
  ...input,
  workflow_id: 'WF-265',
  workflow_name: 'Seller Response Classification & Negotiation Routing Controller',
  status,
  classification,
  counteroffer_amount: counteroffer,
  dynamic_mao: Number.isFinite(dynamicMao) ? dynamicMao : null,
  mao_comparison: Number.isFinite(counteroffer) && Number.isFinite(dynamicMao)
    ? (withinMao ? 'within_mao' : 'above_mao')
    : 'not_comparable',
  next_workflow: route,
  human_review_required: humanReview,
  identity_valid: identityOk,
  blockers,
  seller_response: { received: Boolean(text), text },
  crm_activity: {
    activity_type: 'seller_response_classification',
    workflow_id: 'WF-265',
    classification,
    status,
    counteroffer_amount: counteroffer,
    next_workflow: route,
    human_review_required: humanReview
  }
} }];
